// Decorative samples of computed road loads, not additional simulated commuters.
const COLORS=['#e9dfb9','#b9c8d0','#c06b55','#71999a'];
const rank=(a,b)=>a.priority-b.priority||a.order-b.order;
function keepSample(heap,value,limit){if(heap.length<limit){let i=heap.length;heap.push(value);while(i){const parent=(i-1)>>1;if(rank(heap[parent],value)>=0)break;heap[i]=heap[parent];i=parent;}heap[i]=value;return;}let i=0;while(i*2+1<heap.length){let child=i*2+1;if(child+1<heap.length&&rank(heap[child+1],heap[child])>0)child++;if(rank(heap[child],value)<=0)break;heap[i]=heap[child];i=child;}heap[i]=value;}

export function trafficPaths(c,limit=180,view=null){const out=[],n=Math.sqrt(c.tiles.length),b=view?.bounds||{x0:0,y0:0,x1:n-1,y1:n-1};if(limit<=0)return out;
 for(let yy=b.y0;yy<=b.y1;yy++)for(let xx=b.x0;xx<=b.x1;xx++){const i=yy*n+xx,t=c.tiles[i];for(const elevated of [false,true]){if(elevated?!t.highway:t.type!=='road')continue;const load=elevated?t.highwayTraffic:t.traffic;if(!(load>0))continue;for(const [dx,dy]of [[1,0],[0,1]]){const x=t.x+dx,y=t.y+dy;if(x>=n||y>=n)continue;const next=c.tiles[y*n+x],axis=dx?'x':'y';if(elevated?!next.highway:next.type!=='road')continue;const a=elevated?t.highwayAxis:t.bridgeAxis,b=elevated?next.highwayAxis:next.bridgeAxis;if(t.terrain==='water'&&a!==axis||next.terrain==='water'&&b!==axis)continue;const volume=Math.min(load,elevated?next.highwayTraffic:next.traffic);if(!(volume>0)||view&&!view.contains(t.x+dx*.5,t.y+dy*.5))continue;const count=Math.min(3,Math.ceil(volume/(elevated?65:20))),speed=(elevated?.65:.35)/(1+Math.max(0,volume/(elevated?160:40)-1));for(let k=0;k<count;k++){const priority=(Math.imul(i+1,73856093)^Math.imul(k+1+dy*7+(elevated?17:0),19349663)^c.seed)>>>0;const order=i*12+(elevated?6:0)+dy*3+k;if(view&&out.length>=limit&&(priority>out[0].priority||priority===out[0].priority&&order>=out[0].order))continue;const sample={i,next:y*n+x,x:t.x,y:t.y,dx,dy,elevated,count,speed,k,priority,order};if(view)keepSample(out,sample,limit);else out.push(sample);if(!view&&out.length>=limit)return out;}}}}
 // Stable spatial sampling spreads the finite display budget around the camera.
 return view?out.sort(rank):out;
}
export function trafficVehicles(c,seconds,limit=180,paths=trafficPaths(c,limit)){return paths.slice(0,limit).map(({i,next,x,y,dx,dy,elevated,count,speed,k})=>{const direction=(i+k)%2?1:-1,phase=(seconds*speed+i*.618+k/count)%1,f=direction===1?phase:1-phase,lane=direction*.11;return{x:x+dx*f-dy*lane,y:y+dy*f+dx*lane,dx:dx*direction,dy:dy*direction,elevated,color:COLORS[(i+k)%COLORS.length],tile:f<.5?i:next};});}
